import path from 'path';
import fs from 'fs';
import { bool, escapeKotlinString } from '../utils.js';
import { log } from '../../core/logger.js';
const RUNTIME_PERMISSION_RULES = [
    { key: 'camera', manifestPermission: 'android.permission.CAMERA' },
    { key: 'recordAudio', manifestPermission: 'android.permission.RECORD_AUDIO' },
    { key: 'coarseLocation', manifestPermission: 'android.permission.ACCESS_COARSE_LOCATION' },
    { key: 'fineLocation', manifestPermission: 'android.permission.ACCESS_FINE_LOCATION' },
    { key: 'readExternalStorage', manifestPermission: 'android.permission.READ_EXTERNAL_STORAGE', maxSdk: 32 },
    { key: 'writeExternalStorage', manifestPermission: 'android.permission.WRITE_EXTERNAL_STORAGE', maxSdk: 29 },
    { key: 'readMediaImages', manifestPermission: 'android.permission.READ_MEDIA_IMAGES', minSdk: 33 },
    { key: 'readMediaVideo', manifestPermission: 'android.permission.READ_MEDIA_VIDEO', minSdk: 33 },
    { key: 'readMediaAudio', manifestPermission: 'android.permission.READ_MEDIA_AUDIO', minSdk: 33 },
    { key: 'postNotifications', manifestPermission: 'android.permission.POST_NOTIFICATIONS', minSdk: 33 },
];
function gatherLaunchRuntimePermissionRules(config) {
    const permissions = config.permissions;
    if (!permissions)
        return [];
    return RUNTIME_PERMISSION_RULES.filter(rule => permissions[rule.key] === true);
}
function buildRuntimePermissionCode(rules) {
    if (!rules.length)
        return '';
    return rules.map(rule => {
        const conditions = [];
        if (rule.minSdk != null)
            conditions.push(`Build.VERSION.SDK_INT >= ${rule.minSdk}`);
        if (rule.maxSdk != null)
            conditions.push(`Build.VERSION.SDK_INT <= ${rule.maxSdk}`);
        if (!conditions.length)
            return `            add("${rule.manifestPermission}")`;
        return `            if (${conditions.join(' && ')}) add("${rule.manifestPermission}")`;
    }).join('\n');
}
export function writeMainActivity(config, kotlinDir) {
    const appId = config.appId;
    const webview = config.webview;
    const runtimeRules = gatherLaunchRuntimePermissionRules(config);
    const runtimePermissionsCode = buildRuntimePermissionCode(runtimeRules);
    const cacheModeMap = {
        DEFAULT: 'WebSettings.LOAD_DEFAULT',
        CACHE_ELSE_NETWORK: 'WebSettings.LOAD_CACHE_ELSE_NETWORK',
        NO_CACHE: 'WebSettings.LOAD_NO_CACHE',
        CACHE_ONLY: 'WebSettings.LOAD_CACHE_ONLY',
    };
    const forceDarkModeMap = {
        OFF: 'WebSettingsCompat.FORCE_DARK_OFF',
        ON: 'WebSettingsCompat.FORCE_DARK_ON',
        AUTO: 'WebSettingsCompat.FORCE_DARK_AUTO',
    };
    const statusBarCode = (() => {
        if (config.statusBar === 'transparent') {
            return `
        window.setFlags(
            android.view.WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,
            android.view.WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS
        )`;
        }
        if (config.statusBar === 'light') {
            return `
        @Suppress("DEPRECATION")
        window.decorView.systemUiVisibility = android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR`;
        }
        return '';
    })();
    const keepScreenOn = config.keepScreenOn ? `\n        window.addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)` : '';
    const geoClient = webview.geolocationEnabled ? `
        webView.webChromeClient = object : WebChromeClient() {
            override fun onGeolocationPermissionsShowPrompt(
                origin: String,
                callback: GeolocationPermissions.Callback,
            ) {
                callback.invoke(origin, true, false)
            }
        }`
        : '';
    const uaLine = webview.userAgentString ? `        settings.userAgentString = "${escapeKotlinString(webview.userAgentString)}"` : '        // userAgentString: using system default';
    const forceDarkLine = (() => {
        const configured = webview.forceDark ?? 'AUTO';
        const mode = forceDarkModeMap[configured];
        return `
        if (WebViewFeature.isFeatureSupported(WebViewFeature.FORCE_DARK)) {
            WebSettingsCompat.setForceDark(settings, ${mode})
        }`;
    })();
    const kotlin = `package ${appId}

import android.annotation.SuppressLint
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import android.webkit.CookieManager
import android.webkit.GeolocationPermissions
import android.webkit.WebChromeClient
import android.webkit.WebSettings
import android.webkit.WebView
import android.webkit.WebViewClient
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.webkit.WebSettingsCompat
import androidx.webkit.WebViewFeature

/**
 * WebAPKify - generated MainActivity
 * Serves the bundled web app inside a hardware-accelerated, full-screen WebView.
 *
 * Runtime-requestable permissions enabled in webapkify.config.ts are checked on launch.
 * Missing permissions are requested once at startup before the initial WebView load.
 */
class MainActivity : AppCompatActivity() {
    private lateinit var webView: WebView
    private var launchState: Bundle? = null
    private var webViewInitialized = false

    private val runtimePermissions: List<String>
        get() = buildList {
${runtimePermissionsCode}
        }

    private val permissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions(),
    ) {
        continueStartup()
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        launchState = savedInstanceState
${statusBarCode}${keepScreenOn}
        webView = WebView(this)
        setContentView(webView)
        requestLaunchPermissionsOrContinue()
    }

    private fun requestLaunchPermissionsOrContinue() {
        val missingPermissions = runtimePermissions.filter { permission ->
            ContextCompat.checkSelfPermission(this, permission) != PackageManager.PERMISSION_GRANTED
        }

        if (missingPermissions.isEmpty()) {
            continueStartup()
            return
        }

        permissionLauncher.launch(missingPermissions.toTypedArray())
    }

    @SuppressLint("SetJavaScriptEnabled")
    private fun continueStartup() {
        if (!webViewInitialized) {
            configureWebView()
            webViewInitialized = true
        }

        if (launchState != null) {
            webView.restoreState(launchState!!)
            launchState = null
            return
        }

        if (webView.url == null) {
            webView.loadUrl("file:///android_asset/www/index.html")
        }
    }

    @SuppressLint("SetJavaScriptEnabled")
    private fun configureWebView() {
        val settings = webView.settings
        settings.javaScriptEnabled = ${bool(webview.javaScriptEnabled)}
        settings.javaScriptCanOpenWindowsAutomatically = ${bool(webview.javaScriptCanOpenWindowsAutomatically)}
        settings.domStorageEnabled = ${bool(webview.domStorageEnabled)}
        settings.databaseEnabled = ${bool(webview.databaseEnabled)}
        settings.loadsImagesAutomatically = ${bool(webview.loadsImagesAutomatically)}
        settings.blockNetworkImage = ${bool(webview.blockNetworkImage)}
        settings.blockNetworkLoads = ${bool(webview.blockNetworkLoads)}
        settings.mediaPlaybackRequiresUserGesture = ${bool(webview.mediaPlaybackRequiresUserGesture)}
        settings.useWideViewPort = ${bool(webview.useWideViewPort)}
        settings.loadWithOverviewMode = ${bool(webview.loadWithOverviewMode)}
        settings.builtInZoomControls = ${bool(webview.builtInZoomControls)}
        settings.displayZoomControls = ${bool(webview.displayZoomControls)}
        settings.textZoom = ${webview.textZoom ?? 100}
        settings.cacheMode = ${cacheModeMap[webview.cacheMode ?? 'DEFAULT']}
        settings.allowFileAccessFromFileURLs = ${bool(webview.allowFileAccessFromFileURLs)}
        @Suppress("DEPRECATION")
        settings.allowUniversalAccessFromFileURLs = ${bool(webview.allowUniversalAccessFromFileURLs)}
        settings.safeBrowsingEnabled = ${bool(webview.safeBrowsingEnabled)}
        settings.mixedContentMode = if (${bool(webview.allowMixedContent)}) {
            WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
        } else {
            WebSettings.MIXED_CONTENT_NEVER_ALLOW
        }
        settings.setGeolocationEnabled(${bool(webview.geolocationEnabled)})
${geoClient}
${uaLine}
${forceDarkLine}

        if (WebViewFeature.isFeatureSupported(WebViewFeature.ALGORITHMIC_DARKENING)) {
            WebSettingsCompat.setAlgorithmicDarkeningAllowed(settings, ${bool(webview.algorithmicDarkeningAllowed)})
        }

        val cookieManager = CookieManager.getInstance()
        cookieManager.setAcceptCookie(${bool(webview.acceptCookies)})
        cookieManager.setAcceptThirdPartyCookies(webView, ${bool(webview.acceptThirdPartyCookies)})

        webView.webViewClient = WebViewClient()
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        if (::webView.isInitialized) {
            webView.saveState(outState)
        }
    }

    @Deprecated("Deprecated in Java")
    override fun onBackPressed() {
        if (::webView.isInitialized && webView.canGoBack()) {
            webView.goBack()
            return
        }

        @Suppress("DEPRECATION")
        super.onBackPressed()
    }
}`;
    fs.mkdirSync(path.join(kotlinDir), { recursive: true });
    fs.writeFileSync(path.join(kotlinDir, 'MainActivity.kt'), kotlin);
    log.dim('  MainActivity.kt');
}
